#!/usr/bin/env python3
"""Chesky's stored knowledge base. Writes js/chat-kb.js.

Each entry: keywords (matched against what the visitor types), a reply, optional link/chip codes.
Honesty rule: only state facts that are on the site. For anything else (price, timing, security,
integrations, team details...) the reply says the team will answer and offers a human handoff.

Run from the repo root:  python3 tools/kb.py   (tools/build.py runs it too)
"""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from build import PROJECTS

E = []

def add(id, keys, reply, l=(), c=(), p=0, n=(), a=None, short=False):
    E.append(dict(i=id, k=list(keys), r=reply, l=list(l), c=list(c), p=p, n=list(n), a=a, s=short))

