add('def_shul', ['what does shul mean', 'what is a shul', 'shul meaning', 'what is shul', 'shul means', 'meaning of shul'], "Shul is the Yiddish word for synagogue. Everything Shul builds custom software for nonprofits, shuls included.", c=MAIN, p=2)
add('def_name', ['why the name', 'name meaning', 'why everything shul', 'where does the name come from', 'what does everything shul mean', 'story behind the name', 'origin of the name', 'name origin', 'why is it called'], "I don't know the story behind the name, but the team would be glad to tell you. Want me to pass on the question?", a='offer', c=[TEAM, 'No thanks'])
add('def_prepaid', ['what is a prepaid card', 'how do prepaid cards work', 'how do the cards work', 'what are the cards', 'how do the gift cards work', 'how does the gift card work', 'how do gift cards work'], "In Kipas Hair BP, approved applicants receive prepaid cards that are loaded and activated through the platform, and the store spend and balances are tracked live.", l=['p:kipashairbp'], c=['Kipas Hair BP features', TEAM], p=2)
add('def_kvitel', ['kvitel meaning', 'meaning of kvitel', 'what are kvitlach', 'define kvitel'], "A kvitel is a written note of names and requests, traditionally given to a Rebbe. DRM can generate them in Hebrew and English.", l=['p:drm'], c=['DRM features', TEAM], p=3)

# ---------------------------------------------------------------- we are small / not technical / situations
add('sit_small', ['we are small', "we're small", 'small shul', 'small organization', 'small nonprofit', 'tiny', 'just a few people', 'small group', 'small budget', 'only a few members', 'small community', 'a small one', 'not a big organization', 'we are a small'], "Organization size isn't the question, fit is. Every platform is designed around how your organization actually runs. Tell the team about yours and they'll say what makes sense.", a='offer', c=[TEAM, 'No thanks'])
add('sit_large', ['we are large', "we're large", 'large organization', 'big organization', 'big shul', 'large shul', 'thousands of', 'hundreds of members', '500 members', '1000 members', 'many members', 'lots of donors', 'huge', 'enterprise', 'multiple locations', 'multiple branches', 'several locations', 'multi location', 'multi-location', 'network of'], "Larger setups are worth a conversation. Tell the team about the scale you have in mind and they'll go through it with you.", a='offer', c=[TEAM, 'No thanks'])
add('sit_new', ['just starting', 'just started', 'new organization', 'new shul', 'new nonprofit', 'start up', 'startup', 'starting a shul', 'starting a nonprofit', 'brand new', 'from the ground up', 'launching a nonprofit', 'we are new', "we're new", 'first time', 'never done this', 'never built'], "Starting out is a good time to get it right. Tell the team where you are and what you're trying to build, and they'll guide you.", a='handoff')
add('sit_excel', ['we use excel', 'using excel', 'we use spreadsheets', 'spreadsheet today', 'we use paper', 'paper based', 'paper-based', 'by hand', 'manually', 'manual process', 'manual work', 'we do it manually', 'google sheets today', 'filing cabinet', 'notebooks', 'pen and paper', 'old system', 'outdated system', 'old software', 'our current tool', 'what we use now'], "A lot of organizations come to us because spreadsheets and paper have stopped keeping up. Tell the team what you do today and where it hurts, and they'll show you what could be better.", a='handoff')
add('sit_nontech', ['not technical', 'non technical', 'non-technical', 'no it person', 'no tech person', "don't have an it", 'dont have an it', 'not tech savvy', 'not good with computers', 'not good with technology', 'we are not techy', 'complicated', 'too complicated', 'hard to use', 'difficult', 'overwhelming', 'where do i begin', 'dont know where to start', "don't know where to start", 'i have no idea', 'no idea what i need', 'not sure what we need', 'not sure what i need'], "You don't need to be technical. We start by learning how your organization runs, then design around your people. If you're not sure what you need, tell the team what's slowing you down and they'll take it from there.", l=['process'], a='handoff')
add('sit_prepare', ['what do i need to prepare', 'what do you need from us', 'what info do you need', 'what information do you need', 'what should i send', 'what should i include', 'what do i say', 'how do i describe', 'what should i tell you', 'what to include in my message', 'how detailed', 'before we start', 'before i contact', 'what do i bring', 'what should i have ready', 'requirements from us'], "No special preparation. Just tell the team what your organization does, what's slowing you down, and roughly what you're hoping for. They'll ask the rest.", a='handoff')
add('sit_forprofit', ['for profit', 'for-profit', 'business', 'my business', 'our business', 'company software', 'startup software', 'small business', 'corporate', 'commercial', 'private company', 'individual', 'personal project', 'for myself', 'not a nonprofit', 'we are not a nonprofit', 'we are a business'], "Our focus is custom software for nonprofits. If you run something different, tell the team about it and they'll say whether it's a fit.", a='handoff')
add('sit_decision', ['how do i choose', 'which one should i choose', 'which platform is right', 'which one is right for me', 'which one do i need', 'what do you recommend', 'recommend something', 'what would you suggest', 'help me choose', 'which is best', 'best platform', 'where should i start', 'recommendation for us'], "Tell me what you're trying to do and I'll point you to the closest platform. For example: tracking donors, selling event tickets, running a live fundraiser, or a gift-card assistance program.", c=['Track donors', 'Sell event tickets', 'Run a live fundraiser', 'Gift card program'], p=1)
add('pick_donors', ['track donors'], "For tracking donors, DRM is our donor relationship manager: live totals, recurring charges, follow-ups and receipts in one dashboard.", l=['p:drm'], c=['DRM features', TEAM], p=4)
add('pick_tickets', ['sell event tickets'], "For events and dinners, Mamudem handles tickets, check-in scanning and a live attendee list.", l=['p:mamudem'], c=['Mamudem features', TEAM], p=4)
add('pick_live', ['run a live fundraiser'], "For a live fundraiser, Fundraise Wall shows donations in real time for the room, with a campaign dashboard behind it.", l=['p:fundraise'], c=['Fundraise Wall features', TEAM], p=4)
add('pick_cards', ['gift card program'], "For gift-card assistance, Kipas Hair BP handles registration, approvals, prepaid cards and spend tracking.", l=['p:kipashairbp'], c=['Kipas Hair BP features', TEAM], p=4)
add('sit_compare_tools', ['like salesforce', 'like donorperfect', 'like blackbaud', 'like quickbooks', 'like wix', 'like squarespace', 'like zoho', 'like hubspot', 'like eventbrite', 'like givebutter', 'like zeffy', 'like paypal', 'like venmo', 'like pushpay', 'like shulcloud', 'like shulcloud', 'better than salesforce', 'better than eventbrite', 'vs eventbrite', 'vs salesforce', 'vs donorperfect', 'vs blackbaud', 'vs shulcloud', 'instead of eventbrite', 'instead of salesforce'], "I can't compare to other products fairly. What I can say is that ours are built from scratch around how your organization runs. For a real comparison, the team can walk through it with you.", a='offer', c=[TEAM, 'No thanks'])
add('sit_users_roles', ['multiple users', 'multiple admins', 'staff accounts', 'user accounts', 'user roles', 'roles', 'permissions', 'who can log in', 'different access', 'access levels', 'volunteers can', 'give access', 'share access', 'team members use', 'how many users', 'user limit', 'seats'], "I don't have details about user accounts and permissions for each platform. The team can tell you what's possible for yours. Want me to ask?", a='offer', c=[TEAM, 'No thanks'])
